'use strict';
/* GROK GOLD 92 QUALITY OPTIMIZER — current live core, DEV ranks only, HOLD untouched.
   Keeps EMA9/21 fresh cross, H1 EMA200 alignment, SL=1.5 ATR, TP=.8R unchanged.
   Tests entry quality: RSI, volume spike, EMA gap, H1 ADX, H1 EMA200 distance.
*/
const fs=require('fs'),P='data/xauusd-m5-dukascopy.json';
const M=JSON.parse(fs.readFileSync(P,'utf8')).map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c),v:+(x.volume??x.v??0)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t);
function ema(v,p){let a=Array(v.length).fill(NaN),k=2/(p+1),e=v[0];for(let i=0;i<v.length;i++){if(i)e=v[i]*k+e*(1-k);if(i>=p-1)a[i]=e}return a}function rsi(v,p=14){let a=Array(v.length).fill(NaN),ag=0,al=0;for(let i=1;i<v.length;i++){let d=v[i]-v[i-1],g=Math.max(d,0),l=Math.max(-d,0);if(i<=p){ag+=g;al+=l;if(i===p){ag/=p;al/=p;a[i]=al?100-100/(1+ag/al):100}}else{ag=(ag*(p-1)+g)/p;al=(al*(p-1)+l)/p;a[i]=al?100-100/(1+ag/al):100}}return a}function atr(c,p=14){let a=Array(c.length).fill(NaN),q=[],s=0;for(let i=1;i<c.length;i++){let z=Math.max(c[i].h-c[i].l,Math.abs(c[i].h-c[i-1].c),Math.abs(c[i].l-c[i-1].c));q.push(z);s+=z;if(q.length>p)s-=q.shift();if(q.length===p)a[i]=s/p}return a}function adx(c,p=14){let o=Array(c.length).fill(NaN),tr=Array(c.length).fill(0),pd=Array(c.length).fill(0),md=Array(c.length).fill(0);for(let i=1;i<c.length;i++){let up=c[i].h-c[i-1].h,dn=c[i-1].l-c[i].l;pd[i]=up>dn&&up>0?up:0;md[i]=dn>up&&dn>0?dn:0;tr[i]=Math.max(c[i].h-c[i].l,Math.abs(c[i].h-c[i-1].c),Math.abs(c[i].l-c[i-1].c))}let tn=0,pn=0,mn=0;for(let i=1;i<=p;i++){tn+=tr[i];pn+=pd[i];mn+=md[i]}let dx=Array(c.length).fill(NaN),seed=0,n=0,last=NaN;for(let i=p;i<c.length;i++){if(i>p){tn=tn-tn/p+tr[i];pn=pn-pn/p+pd[i];mn=mn-mn/p+md[i]}if(tn>0){let a=100*pn/tn,b=100*mn/tn;if(a+b)dx[i]=100*Math.abs(a-b)/(a+b)}if(Number.isFinite(dx[i])){if(n<p){seed+=dx[i];n++;if(n===p)last=o[i]=seed/p}else last=o[i]=(last*(p-1)+dx[i])/p}}return o}function agg(ms){let a=[],z,k0;for(const x of M){let k=Math.floor(x.t/ms)*ms;if(k!==k0){if(z)a.push(z);z={t:k,o:x.o,h:x.h,l:x.l,c:x.c,v:x.v};k0=k}else{z.h=Math.max(z.h,x.h);z.l=Math.min(z.l,x.l);z.c=x.c;z.v+=x.v}}if(z)a.push(z);return a}
const H=agg(3600000),C=M.map(x=>x.c),E9=ema(C,9),E21=ema(C,21),R=rsi(C),A=atr(M),HC=H.map(x=>x.c),HE200=ema(HC,200),HA=atr(H),HX=adx(H);let hp=0;const HI=Array(M.length).fill(-1);for(let i=0;i<M.length;i++){while(hp+1<H.length&&H[hp+1].t+3600000<=M[i].t)hp++;HI[i]=(H[hp]&&H[hp].t+3600000<=M[i].t)?hp:-1}function va(i){if(i<20)return NaN;let s=0;for(let j=i-20;j<i;j++)s+=M[j].v;return s/20}
function run(q){let out=[],p=null;for(let i=250;i<M.length-1;i++){if(p){let b=M[i],sl=p.side==='BUY'?b.l<=p.sl:b.h>=p.sl,tp=p.side==='BUY'?b.h>=p.tp:b.l<=p.tp;if(sl||tp){let px=sl?p.sl:p.tp;out.push({t:M[p.si].t,side:p.side,r:(p.side==='BUY'?px-p.en:p.en-px)/p.risk});p=null}if(p)continue}let h=HI[i];if(h<205||![E9[i],E21[i],E9[i-1],E21[i-1],R[i],A[i],HE200[h],HA[h],HX[h]].every(Number.isFinite))continue;let up=E9[i-1]<=E21[i-1]&&E9[i]>E21[i],dn=E9[i-1]>=E21[i-1]&&E9[i]<E21[i],side=null;if(up&&R[i]>q.rb)side='BUY';if(dn&&R[i]<q.rs)side='SELL';if(!side||Math.abs(E9[i]-E21[i])/A[i]<q.gap)continue;let av=va(i);if(!(av>0&&M[i].v>=av*q.vol)||HX[h]<q.adx)continue;let bias=HC[h]>HE200[h]?'BUY':HC[h]<HE200[h]?'SELL':null;if(side!==bias||Math.abs(HC[h]-HE200[h])/HA[h]<q.dist)continue;let en=M[i+1].o,risk=A[i]*1.5;p={side,en,risk,sl:side==='BUY'?en-risk:en+risk,tp:side==='BUY'?en+risk*.8:en-risk*.8,si:i}}return out}
function S(a){let gp=0,gl=0,w=0,e=0,pk=0,dd=0,ls=0,mx=0;for(const x of a){e+=x.r;if(x.r>0){w++;gp+=x.r;ls=0}else{gl+=-x.r;ls++;mx=Math.max(mx,ls)}pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:gl?gp/gl:Infinity,net:e,dd,ls:mx}}const F=s=>`T${s.n} WR${s.wr.toFixed(1)} PF${Number.isFinite(s.pf)?s.pf.toFixed(2):'∞'} N${s.net>=0?'+':''}${s.net.toFixed(2)}R DD${s.dd.toFixed(2)} LS${s.ls}`;
const split=M[0].t+(M.at(-1).t-M[0].t)*.75,base={rb:52,rs:48,vol:1.25,gap:.04,adx:20,dist:.10},bt=run(base),bd=bt.filter(x=>x.t<split),bh=bt.filter(x=>x.t>=split),BSD=S(bd),BSH=S(bh);console.log('GROK92 QUALITY OPTIMIZER\nSplit '+new Date(split).toISOString());console.log('BASE DEV ',F(BSD));console.log('BASE HOLD',F(BSH));console.log('BASE ALL ',F(S(bt)));
let all=[],id=0;for(const rb of[52,54,56])for(const rs of[48,46,44])for(const vol of[1.25,1.4,1.6])for(const gap of[.04,.06,.08,.12])for(const adx of[20,22,25,28])for(const dist of[.10,.15,.20,.30]){let q={rb,rs,vol,gap,adx,dist},t=run(q),d=t.filter(x=>x.t<split),h=t.filter(x=>x.t>=split),sd=S(d),sh=S(h);if(sd.n<70||sh.n<20||sd.n<BSD.n*.45)continue;let score=(sd.pf-BSD.pf)*2+(sd.wr-BSD.wr)/20+(BSD.dd-sd.dd)/5;all.push({id:++id,q,sd,sh,score})}all.sort((a,b)=>b.score-a.score);function line(x){let q=x.q;return`#${x.id} RSI>${q.rb}/<${q.rs} VOL>=${q.vol} GAP>=${q.gap} ADX>=${q.adx} DIST>=${q.dist} | DEV ${F(x.sd)} | HOLD ${F(x.sh)}`};console.log('\n🏆 TOP 20 — DEV RANKING; HOLD NEVER RANKED');all.slice(0,20).forEach(x=>console.log(line(x)));let robust=all.filter(x=>x.sh.pf>=BSH.pf&&x.sh.wr>=BSH.wr&&x.sh.dd<=BSH.dd*1.1&&x.sd.pf>BSD.pf&&x.sd.wr>=BSD.wr);console.log('\n🛡️ ROBUST SHORTLIST');robust.slice(0,25).forEach(x=>console.log(line(x)));if(!robust.length)console.log('NONE — do not change live.');